static int test_user_variable_foundation_execution(void) {
    // NOLINTBEGIN(readability-function-size,readability-magic-numbers)
    static const char *const variable_columns[] = {"missing", "answer", "text_value", "null_value"};
    static const char *const variable_values[] = {NULL, "42", "hello", NULL};
    static const char *const quoted_columns[] = {"lower_a", "dash_value"};
    static const char *const quoted_values[] = {"7", "quoted"};
    static const char *const assignment_columns[] = {"a_value", "b_value", "c_value"};
    static const char *const assignment_values[] = {"5", "11", NULL};
    static const char *const expression_assignment_columns[] =
        {"assigned", "after_a", "b", "bumped", "final_a", "final_b"};
    static const char *const expression_assignment_values[] = {"1", "1", "2", "6", "6", "2"};
    static const char *const nested_assignment_columns[] = {"a", "b", "c"};
    static const char *const nested_assignment_values[] = {"1", "2", "2"};
    static const struct expected_result_metadata expression_assignment_metadata[] = {
        {"assigned",
         NULL,
         NULL,
         NULL,
         NULL,
         NULL,
         2U,
         MYLITE_FIELD_TYPE_LONGLONG,
         0U,
         63U,
         MYLITE_FIELD_FLAG_NOT_NULL | MYLITE_FIELD_FLAG_BINARY | MYLITE_FIELD_FLAG_NUM,
         0U,
         0},
    };
    static const char *const mixed_set_columns[] = {
        "old_uc",
        "current_uc",
        "after_uc",
        "old_notes",
        "current_notes",
        "after_notes",
        "old_sqlbin",
        "current_sqlbin",
        "after_sqlbin",
    };
    static const char *const mixed_set_values[] = {"1", "0", "1", "1", "0", "1", "1", "0", "1"};
    static const char *const restored_set_columns[] = {"uc", "notes", "sqlbin"};
    static const char *const restored_set_values[] = {"1", "1", "1"};
    static const char *const id_column[] = {"id"};
    static const char *const greater_than_threshold_values[] = {"2", "3"};
    static const char *const table_assignment_columns[] = {"seen", "after_seen"};
    static const char *const table_assignment_values[] = {"2", "2"};
    static const char *const row_columns[] = {"id", "note"};
    static const char *const final_row_values[] = {"1", "alpha", "2", "matched"};
    static const struct expected_result_metadata metadata[] = {
        {"missing",
         NULL,
         NULL,
         NULL,
         NULL,
         NULL,
         65535U,
         MYLITE_FIELD_TYPE_VAR_STRING,
         31U,
         63U,
         MYLITE_FIELD_FLAG_BINARY,
         MYLITE_FIELD_FLAG_NOT_NULL,
         1},
        {"answer",
         NULL,
         NULL,
         NULL,
         NULL,
         NULL,
         21U,
         MYLITE_FIELD_TYPE_LONGLONG,
         0U,
         63U,
         MYLITE_FIELD_FLAG_BINARY | MYLITE_FIELD_FLAG_NUM,
         MYLITE_FIELD_FLAG_NOT_NULL,
         1},
        {"text_value",
         NULL,
         NULL,
         NULL,
         NULL,
         NULL,
         268435440U,
         MYLITE_FIELD_TYPE_LONG_BLOB,
         31U,
         255U,
         0U,
         MYLITE_FIELD_FLAG_NOT_NULL | MYLITE_FIELD_FLAG_BINARY | MYLITE_FIELD_FLAG_BLOB,
         1},
        {"null_value",
         NULL,
         NULL,
         NULL,
         NULL,
         NULL,
         16777215U,
         MYLITE_FIELD_TYPE_MEDIUM_BLOB,
         31U,
         63U,
         MYLITE_FIELD_FLAG_BINARY | MYLITE_FIELD_FLAG_BLOB,
         MYLITE_FIELD_FLAG_NOT_NULL,
         1},
    };
    mylite_db *database = NULL;
    mylite_stmt *stmt = NULL;
    int failures = 0;

    failures +=
        expect_status(mylite_open_memory(&database), MYLITE_OK, "open user variable database");

    failures += execute_sql(
        database,
        "SET @answer = 42, @text_value = 'hello', @null_value = NULL",
        MYLITE_DONE
    );
    failures += prepare_sql(
        database,
        "SELECT @missing AS missing, @answer AS answer, "
        "@text_value AS text_value, @null_value AS null_value",
        MYLITE_OK,
        &stmt
    );
    failures += expect_column_names(stmt, variable_columns, 4, "user variable columns");
    failures += expect_result_metadata(stmt, metadata, 4, "user variable metadata");
    failures += expect_status(mylite_step(stmt), MYLITE_ROW, "user variable row");
    for (int column = 0; column < 4; ++column) {
        if (variable_values[column] == NULL) {
            failures += expect_null_text(mylite_column_text(stmt, column), "user variable value");
        } else {
            failures += expect_string(
                mylite_column_text(stmt, column),
                variable_values[column],
                "user variable value"
            );
        }
    }
    failures += expect_status(mylite_step(stmt), MYLITE_DONE, "user variable done");
    mylite_finalize(stmt);
    stmt = NULL;

    failures += execute_sql(database, "SET @A = 7, @'dash-name' = 'quoted'", MYLITE_DONE);
    failures += expect_select_rows(
        database,
        "SELECT @a AS lower_a, @`dash-name` AS dash_value",
        quoted_columns,
        2,
        quoted_values,
        1,
        "quoted user variable lookup"
    );

    failures += execute_sql(database, "SET @a = 10", MYLITE_DONE);
    failures += execute_sql(database, "SET @a = 1, @b = @a + 1, @a = 5, @c = @b + @a", MYLITE_DONE);
    failures += expect_select_rows(
        database,
        "SELECT @a AS a_value, @b AS b_value, @c AS c_value",
        assignment_columns,
        3,
        assignment_values,
        1,
        "multi-assignment statement-start values"
    );

    failures += execute_sql(database, "SET @expr_a = 10, @expr_b = NULL", MYLITE_DONE);
    failures += prepare_sql(
        database,
        "SELECT @expr_a := 1 AS assigned, @expr_a AS after_a, "
        "@expr_b := @expr_a + 1 AS b, @expr_a := @expr_a + 5 AS bumped, "
        "@expr_a AS final_a, @expr_b AS final_b",
        MYLITE_OK,
        &stmt
    );
    failures += expect_column_names(
        stmt,
        expression_assignment_columns,
        6,
        "user variable expression assignment columns"
    );
    failures += expect_status(mylite_step(stmt), MYLITE_ROW, "user variable assignment row");
    for (int column = 0; column < 6; ++column) {
        failures += expect_string(
            mylite_column_text(stmt, column),
            expression_assignment_values[column],
            "user variable expression assignment value"
        );
    }
    failures += expect_int(
        mylite_warning_count(database),
        3,
        "user variable expression assignment warning count"
    );
    for (int warning = 0; warning < 3; ++warning) {
        failures += expect_int(
            (int)mylite_warning_code(database, warning),
            1287,
            "user variable expression assignment warning code"
        );
    }
    failures += expect_status(mylite_step(stmt), MYLITE_DONE, "user variable assignment done");
    mylite_finalize(stmt);
    stmt = NULL;

    failures += prepare_sql(database, "SELECT @meta_assign := 1 AS assigned", MYLITE_OK, &stmt);
    failures += expect_result_metadata(
        stmt,
        expression_assignment_metadata,
        1,
        "user variable assignment metadata"
    );
    failures += expect_status(mylite_step(stmt), MYLITE_ROW, "user variable metadata row");
    failures += expect_string(mylite_column_text(stmt, 0), "1", "user variable metadata value");
    failures +=
        expect_int(mylite_warning_count(database), 1, "user variable metadata warning count");
    failures += expect_int(
        (int)mylite_warning_code(database, 0),
        1287,
        "user variable metadata warning code"
    );
    failures += expect_status(mylite_step(stmt), MYLITE_DONE, "user variable metadata done");
    mylite_finalize(stmt);
    stmt = NULL;

    failures += execute_sql(database, "SET @set_a = 10, @set_b = NULL, @set_c = NULL", MYLITE_DONE);
    failures += execute_sql(
        database,
        "SET @set_a = 1, @set_b = (@set_a := 2), @set_c = @set_a",
        MYLITE_DONE
    );
    failures += expect_int(
        mylite_warning_count(database),
        1,
        "nested user variable assignment warning count"
    );
    failures += expect_int(
        (int)mylite_warning_code(database, 0),
        1287,
        "nested user variable assignment warning code"
    );
    failures += expect_select_rows(
        database,
        "SELECT @set_a AS a, @set_b AS b, @set_c AS c",
        nested_assignment_columns,
        3,
        nested_assignment_values,
        1,
        "nested SET user variable expression assignment"
    );
    failures += execute_sql(
        database,
        "SET @old_unique_checks = @@unique_checks, unique_checks = 0, "
        "@after_unique_checks = @@unique_checks, "
        "@old_sql_notes = @@sql_notes, sql_notes = 0, @after_sql_notes = @@sql_notes, "
        "@old_sql_log_bin = @@SESSION.sql_log_bin, @@SESSION.sql_log_bin = 0, "
        "@after_sql_log_bin = @@SESSION.sql_log_bin",
        MYLITE_DONE
    );
    failures += expect_select_rows(
        database,
        "SELECT @old_unique_checks AS old_uc, @@unique_checks AS current_uc, "
        "@after_unique_checks AS after_uc, @old_sql_notes AS old_notes, "
        "@@sql_notes AS current_notes, @after_sql_notes AS after_notes, "
        "@old_sql_log_bin AS old_sqlbin, @@sql_log_bin AS current_sqlbin, "
        "@after_sql_log_bin AS after_sqlbin",
        mixed_set_columns,
        9,
        mixed_set_values,
        1,
        "mixed SET snapshots user and system assignments"
    );
    failures += execute_sql(database, "SET unique_checks = @old_unique_checks", MYLITE_DONE);
    failures += execute_sql(database, "SET sql_notes = @old_sql_notes", MYLITE_DONE);
    failures += execute_sql(database, "SET @@SESSION.sql_log_bin = @old_sql_log_bin", MYLITE_DONE);
    failures += expect_select_rows(
        database,
        "SELECT @@unique_checks AS uc, @@sql_notes AS notes, @@sql_log_bin AS sqlbin",
        restored_set_columns,
        3,
        restored_set_values,
        1,
        "system variable restore from user variables"
    );

    failures += execute_sql(database, "CREATE DATABASE mylite_user_variables", MYLITE_DONE);
    failures += execute_sql(database, "USE mylite_user_variables", MYLITE_DONE);
    failures += execute_sql(
        database,
        "CREATE TABLE variable_rows ("
        "id INT PRIMARY KEY, "
        "note VARCHAR(20))",
        MYLITE_DONE
    );
    failures += execute_sql(
        database,
        "INSERT INTO variable_rows VALUES "
        "(1,'alpha'),(2,'beta'),(3,'gamma')",
        MYLITE_DONE
    );
    failures += execute_sql(database, "SET @threshold = 1, @label = 'matched'", MYLITE_DONE);
    failures += prepare_sql(
        database,
        "SELECT @row_seen := id AS seen, @row_seen AS after_seen "
        "FROM variable_rows WHERE id = 2",
        MYLITE_OK,
        &stmt
    );
    failures += expect_column_names(
        stmt,
        table_assignment_columns,
        2,
        "table user variable assignment columns"
    );
    failures += expect_status(mylite_step(stmt), MYLITE_ROW, "table user variable assignment row");
    for (int column = 0; column < 2; ++column) {
        failures += expect_string(
            mylite_column_text(stmt, column),
            table_assignment_values[column],
            "table user variable assignment value"
        );
    }
    failures += expect_int(
        mylite_warning_count(database),
        1,
        "table user variable assignment warning count"
    );
    failures += expect_int(
        (int)mylite_warning_code(database, 0),
        1287,
        "table user variable assignment warning code"
    );
    failures +=
        expect_status(mylite_step(stmt), MYLITE_DONE, "table user variable assignment done");
    mylite_finalize(stmt);
    stmt = NULL;

    failures += expect_select_rows(
        database,
        "SELECT id FROM variable_rows "
        "WHERE id > @threshold ORDER BY id",
        id_column,
        1,
        greater_than_threshold_values,
        2,
        "user variable WHERE predicate"
    );
    failures += execute_sql_expect_done_affected(
        database,
        "UPDATE variable_rows SET note = @label WHERE id = @threshold + 1",
        1,
        "user variable UPDATE expression"
    );
    failures += execute_sql_expect_done_affected(
        database,
        "DELETE FROM variable_rows WHERE id = @threshold + 2",
        1,
        "user variable DELETE predicate"
    );
    failures += expect_select_rows(
        database,
        "SELECT id, note FROM variable_rows ORDER BY id",
        row_columns,
        2,
        final_row_values,
        2,
        "user variable DML final rows"
    );

    mylite_close(database);
    // NOLINTEND(readability-function-size,readability-magic-numbers)
    return failures;
}

static int test_sql_prepared_statements_execution(void) {
    // NOLINTBEGIN(readability-function-size,readability-magic-numbers)
    static const char *const id_name_columns[] = {"id", "name"};
    static const char *const nbe_columns[] = {"h", "l"};
    static const char *const inserted_row_values[] = {"4", "can't"};
    mylite_db *database = NULL;
    mylite_stmt *stmt = NULL;
    int failures = 0;

    failures +=
        expect_status(mylite_open_memory(&database), MYLITE_OK, "open prepared statement database");
    failures += execute_sql(database, "CREATE DATABASE mylite_prepared_statements", MYLITE_DONE);
    failures += execute_sql(database, "USE mylite_prepared_statements", MYLITE_DONE);
    failures += execute_sql(
        database,
        "CREATE TABLE prepared_statement_rows ("
        "id INT PRIMARY KEY, "
        "name VARCHAR(20), "
        "note VARCHAR(20))",
        MYLITE_DONE
    );
    failures += execute_sql(
        database,
        "INSERT INTO prepared_statement_rows VALUES "
        "(1,'alpha','a'),(2,'beta','b'),(3,'gamma','c')",
        MYLITE_DONE
    );

    failures +=
        execute_sql(database, "PREPARE add_one FROM 'SELECT ? + 1 AS plus_one'", MYLITE_DONE);
    failures += execute_sql(database, "SET @x = 41", MYLITE_DONE);
    failures += prepare_sql(database, "EXECUTE add_one USING @x", MYLITE_OK, &stmt);
    failures += expect_status(mylite_step(stmt), MYLITE_ROW, "execute add_one row");
    failures +=
        expect_column_names(stmt, (const char *const[]){"plus_one"}, 1, "execute add_one columns");
    failures += expect_string(mylite_column_text(stmt, 0), "42", "execute add_one value");
    failures += expect_status(mylite_step(stmt), MYLITE_DONE, "execute add_one done");
    mylite_finalize(stmt);
    stmt = NULL;

    failures += execute_sql(
        database,
        "SET @sql = 'SELECT id, name FROM prepared_statement_rows "
        "WHERE id > ? ORDER BY id LIMIT ?'",
        MYLITE_DONE
    );
    failures += execute_sql(database, "PREPARE from_var FROM @sql", MYLITE_DONE);
    failures += execute_sql(database, "SET @min_id = 1, @row_limit = 1", MYLITE_DONE);
    failures +=
        prepare_sql(database, "EXECUTE from_var USING @min_id, @row_limit", MYLITE_OK, &stmt);
    failures += expect_status(mylite_step(stmt), MYLITE_ROW, "execute from variable row");
    failures += expect_column_names(stmt, id_name_columns, 2, "execute from variable columns");
    failures += expect_string(mylite_column_text(stmt, 0), "2", "execute from variable id");
    failures += expect_string(mylite_column_text(stmt, 1), "beta", "execute from variable name");
    failures += expect_status(mylite_step(stmt), MYLITE_DONE, "execute from variable done");
    mylite_finalize(stmt);
    stmt = NULL;

    failures += execute_sql(database, "PREPARE MixedName FROM 'SELECT 4 AS v'", MYLITE_DONE);
    failures += prepare_sql(database, "EXECUTE mixedname", MYLITE_OK, &stmt);
    failures += expect_status(mylite_step(stmt), MYLITE_ROW, "case-insensitive execute row");
    failures +=
        expect_column_names(stmt, (const char *const[]){"v"}, 1, "case-insensitive columns");
    failures += expect_string(mylite_column_text(stmt, 0), "4", "case-insensitive value");
    failures += expect_status(mylite_step(stmt), MYLITE_DONE, "case-insensitive execute done");
    mylite_finalize(stmt);
    stmt = NULL;

    failures += execute_sql(database, "PREPARE `select` FROM 'SELECT 3 AS v'", MYLITE_DONE);
    failures += prepare_sql(database, "EXECUTE `select`", MYLITE_OK, &stmt);
    failures += expect_status(mylite_step(stmt), MYLITE_ROW, "quoted execute row");
    failures += expect_string(mylite_column_text(stmt, 0), "3", "quoted execute value");
    failures += expect_status(mylite_step(stmt), MYLITE_DONE, "quoted execute done");
    mylite_finalize(stmt);
    stmt = NULL;

    failures += execute_sql(database, "SET SESSION sql_mode = ''", MYLITE_DONE);
    failures +=
        execute_sql(database, "PREPARE mode_default FROM 'SELECT \"name\" AS v'", MYLITE_DONE);
    failures += execute_sql(database, "SET SESSION sql_mode = 'ANSI_QUOTES'", MYLITE_DONE);
    failures += prepare_sql(database, "EXECUTE mode_default", MYLITE_OK, &stmt);
    failures += expect_status(mylite_step(stmt), MYLITE_ROW, "default-mode prepared row");
    failures += expect_column_names(stmt, (const char *const[]){"v"}, 1, "default-mode columns");
    failures += expect_string(mylite_column_text(stmt, 0), "name", "default-mode value");
    failures += expect_status(mylite_step(stmt), MYLITE_DONE, "default-mode prepared done");
    mylite_finalize(stmt);
    stmt = NULL;

    failures += prepare_sql(
        database,
        "SELECT \"name\" FROM prepared_statement_rows WHERE id = 1",
        MYLITE_OK,
        &stmt
    );
    failures += expect_status(mylite_step(stmt), MYLITE_ROW, "ansi quoted identifier row");
    failures += expect_column_names(
        stmt,
        (const char *const[]){"name"},
        1,
        "ansi quoted identifier columns"
    );
    failures += expect_string(mylite_column_text(stmt, 0), "alpha", "ansi quoted identifier value");
    failures += expect_status(mylite_step(stmt), MYLITE_DONE, "ansi quoted identifier done");
    mylite_finalize(stmt);
    stmt = NULL;

    failures += execute_sql(
        database,
        "PREPARE mode_ansi FROM "
        "'SELECT \"name\" FROM prepared_statement_rows WHERE id = 1'",
        MYLITE_DONE
    );
    failures += execute_sql(database, "SET SESSION sql_mode = ''", MYLITE_DONE);
    failures += prepare_sql(database, "EXECUTE mode_ansi", MYLITE_OK, &stmt);
    failures += expect_status(mylite_step(stmt), MYLITE_ROW, "ansi-mode prepared row");
    failures += expect_column_names(stmt, (const char *const[]){"name"}, 1, "ansi-mode columns");
    failures += expect_string(mylite_column_text(stmt, 0), "alpha", "ansi-mode value");
    failures += expect_status(mylite_step(stmt), MYLITE_DONE, "ansi-mode prepared done");
    mylite_finalize(stmt);
    stmt = NULL;

    failures += execute_sql(database, "SET SESSION sql_mode = 'NO_BACKSLASH_ESCAPES'", MYLITE_DONE);
    failures += execute_sql(
        database,
        "PREPARE mode_nbe FROM "
        "'SELECT HEX(''a\\0b'') AS h, LENGTH(''a\\0b'') AS l'",
        MYLITE_DONE
    );
    failures += execute_sql(database, "SET SESSION sql_mode = ''", MYLITE_DONE);
    failures += prepare_sql(database, "EXECUTE mode_nbe", MYLITE_OK, &stmt);
    failures += expect_status(mylite_step(stmt), MYLITE_ROW, "nbe prepared row");
    failures += expect_column_names(stmt, nbe_columns, 2, "nbe columns");
    failures += expect_string(mylite_column_text(stmt, 0), "615C3062", "nbe hex value");
    failures += expect_string(mylite_column_text(stmt, 1), "4", "nbe length value");
    failures += expect_status(mylite_step(stmt), MYLITE_DONE, "nbe prepared done");
    mylite_finalize(stmt);
    stmt = NULL;

    failures += execute_sql(
        database,
        "PREPARE ins FROM 'INSERT INTO prepared_statement_rows(id, name, note) "
        "VALUES (?, ?, ?)'",
        MYLITE_DONE
    );
    failures += execute_sql(
        database,
        "SET @new_id = 4, @new_name = 'delta', @new_note = 'can''t'",
        MYLITE_DONE
    );
    failures += execute_sql_expect_done_affected(
        database,
        "EXECUTE ins USING @new_id, @new_name, "
        "@new_note",
        1,
        "prepared INSERT affected rows"
    );
    failures += expect_select_rows(
        database,
        "SELECT id, note FROM prepared_statement_rows "
        "WHERE id = 4",
        (const char *const[]){"id", "note"},
        2,
        inserted_row_values,
        1,
        "prepared INSERT stored row"
    );

    failures += execute_sql(database, "PREPARE mismatch FROM 'SELECT ? AS v'", MYLITE_DONE);
    failures += prepare_sql(database, "EXECUTE mismatch", MYLITE_OK, &stmt);
    failures += expect_exec_error(
        stmt,
        database,
        "Incorrect arguments to EXECUTE",
        "prepared parameter count mismatch"
    );
    failures += expect_int(mylite_warning_count(database), 1, "prepared mismatch warning count");
    failures += expect_int(
        (int)mylite_warning_code(database, 0),
        mysql_warning_incorrect_escape_arguments,
        "prepared mismatch warning code"
    );
    mylite_finalize(stmt);
    stmt = NULL;

    failures += prepare_sql(database, "EXECUTE no_such", MYLITE_OK, &stmt);
    failures += expect_exec_error(
        stmt,
        database,
        "Unknown prepared statement handler",
        "unknown prepared execute"
    );
    failures += expect_int(mylite_warning_count(database), 1, "unknown execute warning count");
    failures += expect_int(
        (int)mylite_warning_code(database, 0),
        mysql_warning_unknown_stmt_handler,
        "unknown execute warning code"
    );
    mylite_finalize(stmt);
    stmt = NULL;

    failures += prepare_sql(database, "DEALLOCATE PREPARE no_such", MYLITE_OK, &stmt);
    failures += expect_exec_error(
        stmt,
        database,
        "Unknown prepared statement handler",
        "unknown prepared deallocate"
    );
    failures += expect_int(mylite_warning_count(database), 1, "unknown deallocate warning count");
    failures += expect_int(
        (int)mylite_warning_code(database, 0),
        mysql_warning_unknown_stmt_handler,
        "unknown deallocate warning code"
    );
    mylite_finalize(stmt);
    stmt = NULL;

    failures += execute_sql(database, "PREPARE dup FROM 'SELECT 1 AS v'", MYLITE_DONE);
    failures += execute_sql(database, "PREPARE dup FROM @missing_sql", MYLITE_PARSE_ERROR);
    failures += prepare_sql(database, "EXECUTE dup", MYLITE_OK, &stmt);
    failures += expect_exec_error(
        stmt,
        database,
        "Unknown prepared statement handler",
        "failed duplicate prepare removes old statement"
    );
    mylite_finalize(stmt);
    stmt = NULL;

    failures += prepare_sql(
        database,
        "PREPARE nested_prepare FROM "
        "'PREPARE inner_s FROM ''SELECT 1'''",
        MYLITE_OK,
        &stmt
    );
    failures += expect_exec_error(
        stmt,
        database,
        "not supported in the prepared statement protocol",
        "nested prepared statement rejected"
    );
    failures += expect_int(mylite_warning_count(database), 1, "nested prepare warning count");
    failures += expect_int(
        (int)mylite_warning_code(database, 0),
        mysql_warning_unsupported_prepared_statement,
        "nested prepare warning code"
    );
    mylite_finalize(stmt);
    stmt = NULL;

    failures += execute_sql(database, "DROP PREPARE add_one", MYLITE_DONE);
    failures += prepare_sql(database, "EXECUTE add_one", MYLITE_OK, &stmt);
    failures += expect_exec_error(
        stmt,
        database,
        "Unknown prepared statement handler",
        "drop prepare removes statement"
    );
    mylite_finalize(stmt);
    stmt = NULL;

    failures += execute_sql(database, "DEALLOCATE PREPARE from_var", MYLITE_DONE);
    failures += execute_sql(database, "DEALLOCATE PREPARE mixedname", MYLITE_DONE);
    failures += execute_sql(database, "DEALLOCATE PREPARE `select`", MYLITE_DONE);
    failures += execute_sql(database, "DEALLOCATE PREPARE mode_default", MYLITE_DONE);
    failures += execute_sql(database, "DEALLOCATE PREPARE mode_ansi", MYLITE_DONE);
    failures += execute_sql(database, "DEALLOCATE PREPARE mode_nbe", MYLITE_DONE);
    failures += execute_sql(database, "DEALLOCATE PREPARE ins", MYLITE_DONE);
    failures += execute_sql(database, "DEALLOCATE PREPARE mismatch", MYLITE_DONE);

    mylite_close(database);
    // NOLINTEND(readability-function-size,readability-magic-numbers)
    return failures;
}

static int test_case_expression_execution(void) {
    // NOLINTBEGIN(readability-magic-numbers)
    static const char *const rowless_columns[] = {
        "searched_short",
        "searched_second",
        "null_condition",
        "simple_match",
        "simple_null",
        "omitted_else",
        "nested_case",
    };
    static const struct expected_result_metadata metadata[] = {
        {"case_text",
         NULL,
         NULL,
         NULL,
         NULL,
         NULL,
         12U,
         MYLITE_FIELD_TYPE_VAR_STRING,
         31U,
         255U,
         MYLITE_FIELD_FLAG_NOT_NULL,
         MYLITE_FIELD_FLAG_BINARY,
         0},
        {"case_int",
         NULL,
         NULL,
         NULL,
         NULL,
         NULL,
         3U,
         MYLITE_FIELD_TYPE_LONGLONG,
         0U,
         63U,
         MYLITE_FIELD_FLAG_NOT_NULL | MYLITE_FIELD_FLAG_BINARY | MYLITE_FIELD_FLAG_NUM,
         0U,
         0},
        {"case_null",
         NULL,
         NULL,
         NULL,
         NULL,
         NULL,
         0U,
         MYLITE_FIELD_TYPE_NULL,
         0U,
         63U,
         MYLITE_FIELD_FLAG_BINARY | MYLITE_FIELD_FLAG_NUM,
         MYLITE_FIELD_FLAG_NOT_NULL,
         1},
        {"case_decimal",
         NULL,
         NULL,
         NULL,
         NULL,
         NULL,
         4U,
         MYLITE_FIELD_TYPE_NEWDECIMAL,
         1U,
         63U,
         MYLITE_FIELD_FLAG_NOT_NULL | MYLITE_FIELD_FLAG_BINARY | MYLITE_FIELD_FLAG_NUM,
         0U,
         0},
        {"case_func",
         NULL,
         NULL,
         NULL,
         NULL,
         NULL,
         2U,
         MYLITE_FIELD_TYPE_LONGLONG,
         0U,
         63U,
         MYLITE_FIELD_FLAG_NOT_NULL | MYLITE_FIELD_FLAG_BINARY | MYLITE_FIELD_FLAG_NUM,
         0U,
         0},
    };
    static const struct expected_result_metadata binary_metadata[] = {
        {"case_bin_col",
         NULL,
         NULL,
         NULL,
         NULL,
         NULL,
         8U,
         MYLITE_FIELD_TYPE_VAR_STRING,
         31U,
         63U,
         MYLITE_FIELD_FLAG_BINARY,
         MYLITE_FIELD_FLAG_NOT_NULL,
         1},
        {"case_mixed_bin_text",
         NULL,
         NULL,
         NULL,
         NULL,
         NULL,
         32U,
         MYLITE_FIELD_TYPE_VAR_STRING,
         31U,
         63U,
         MYLITE_FIELD_FLAG_BINARY,
         MYLITE_FIELD_FLAG_NOT_NULL,
         1},
        {"case_mixed_text_bin",
         NULL,
         NULL,
         NULL,
         NULL,
         NULL,
         32U,
         MYLITE_FIELD_TYPE_VAR_STRING,
         31U,
         63U,
         MYLITE_FIELD_FLAG_BINARY,
         MYLITE_FIELD_FLAG_NOT_NULL,
         1},
        {"case_null_bin",
         NULL,
         NULL,
         NULL,
         NULL,
         NULL,
         8U,
         MYLITE_FIELD_TYPE_VAR_STRING,
         31U,
         63U,
         MYLITE_FIELD_FLAG_BINARY,
         MYLITE_FIELD_FLAG_NOT_NULL,
         1},
    };
    static const char *const id_column[] = {"id"};
    static const char *const id_label_columns[] = {"id", "label"};
    static const char *const projection_values[] = {
        "1",
        "n=1",
        "2",
        "n=-2",
        "3",
        "nil",
        "4",
        "n=0",
    };
    static const char *const simple_projection_values[] = {
        "1",
        "one",
        "2",
        "minus",
        "3",
        "zero",
        "4",
        "zero",
    };
    static const char *const where_values[] = {"1", "3"};
    static const char *const order_values[] = {"3", "2", "1", "4"};
    static const char *const id_s_columns[] = {"id", "s"};
    static const char *const updated_s_values[] = {"2", "beta"};
    static const char *const v_column[] = {"v"};
    static const char *const v_11[] = {"11"};
    static const char *const order_dml_columns[] = {"id", "marker"};
    static const char *const order_dml_after_update[] = {"1", "a", "2", "hit", "3", "c"};
    static const char *const order_dml_after_delete[] = {"1", "a", "3", "c"};
    mylite_db *database = NULL;
    mylite_stmt *stmt = NULL;
    int failures = 0;

    failures += expect_status(mylite_open_memory(&database), MYLITE_OK, "open CASE database");
    failures += execute_sql(
        database,
        "CREATE DATABASE mylite_case_expression "
        "DEFAULT CHARACTER SET utf8mb4",
        MYLITE_DONE
    );
    failures += execute_sql(database, "USE mylite_case_expression", MYLITE_DONE);

    failures += prepare_sql(
        database,
        "SELECT CASE WHEN 1 THEN 'yes' ELSE 1/0 END AS searched_short, "
        "CASE WHEN 0 THEN 1/0 WHEN 2 THEN 'second' ELSE 'else' END "
        "AS searched_second, "
        "CASE WHEN NULL THEN 'null-branch' ELSE 'else' END "
        "AS null_condition, "
        "CASE 2 WHEN 1 THEN 'one' WHEN 2 THEN 'two' ELSE 'other' END "
        "AS simple_match, "
        "CASE NULL WHEN NULL THEN 'matched' ELSE 'else' END AS simple_null, "
        "CASE WHEN 0 THEN 'no' END AS omitted_else, "
        "CASE WHEN 1 THEN CASE WHEN 0 THEN 2 ELSE 3 END ELSE 4 END "
        "AS nested_case",
        MYLITE_OK,
        &stmt
    );
    failures += expect_column_names(
        stmt,
        rowless_columns,
        (int)(sizeof(rowless_columns) / sizeof(rowless_columns[0])),
        "CASE rowless columns"
    );
    failures += expect_status(mylite_step(stmt), MYLITE_ROW, "CASE rowless row");
    failures += expect_string(mylite_column_text(stmt, 0), "yes", "CASE searched short");
    failures += expect_string(mylite_column_text(stmt, 1), "second", "CASE searched second");
    failures += expect_string(mylite_column_text(stmt, 2), "else", "CASE null condition");
    failures += expect_string(mylite_column_text(stmt, 3), "two", "CASE simple match");
    failures += expect_string(mylite_column_text(stmt, 4), "else", "CASE simple null");
    failures += expect_null_text(mylite_column_text(stmt, 5), "CASE omitted else");
    failures += expect_string(mylite_column_text(stmt, 6), "3", "CASE nested");
    failures += expect_int(mylite_warning_count(database), 0, "CASE rowless warning count");
    failures += expect_status(mylite_step(stmt), MYLITE_DONE, "CASE rowless done");
    mylite_finalize(stmt);
    stmt = NULL;

    failures += prepare_sql(
        database,
        "SELECT CASE WHEN 0 THEN 10 ELSE 1/0 END AS selected_warning",
        MYLITE_OK,
        &stmt
    );
    failures += expect_status(mylite_step(stmt), MYLITE_ROW, "CASE selected warning row");
    failures += expect_null_text(mylite_column_text(stmt, 0), "CASE selected warning result");
    failures += expect_int(mylite_warning_count(database), 1, "CASE selected warning count");
    failures += expect_int(
        (int)mylite_warning_code(database, 0),
        mysql_warning_division_by_zero,
        "CASE selected warning code"
    );
    mylite_finalize(stmt);
    stmt = NULL;

    failures += prepare_sql(
        database,
        "SELECT CASE 1 WHEN 1 THEN 10 WHEN 1/0 THEN 20 ELSE 30 END "
        "AS simple_short",
        MYLITE_OK,
        &stmt
    );
    failures += expect_status(mylite_step(stmt), MYLITE_ROW, "CASE simple short row");
    failures += expect_string(mylite_column_text(stmt, 0), "10", "CASE simple short result");
    failures += expect_int(mylite_warning_count(database), 0, "CASE simple short warning count");
    mylite_finalize(stmt);
    stmt = NULL;

    failures += prepare_sql(
        database,
        "SELECT CASE 1 WHEN 0 THEN 10 WHEN 1/0 THEN 20 ELSE 30 END "
        "AS simple_warning",
        MYLITE_OK,
        &stmt
    );
    failures += expect_status(mylite_step(stmt), MYLITE_ROW, "CASE simple warning row");
    failures += expect_string(mylite_column_text(stmt, 0), "30", "CASE simple warning result");
    failures += expect_int(mylite_warning_count(database), 1, "CASE simple warning count");
    failures += expect_int(
        (int)mylite_warning_code(database, 0),
        mysql_warning_division_by_zero,
        "CASE simple warning code"
    );
    mylite_finalize(stmt);
    stmt = NULL;

    failures += prepare_sql(
        database,
        "SELECT CASE 1/0 WHEN 0 THEN 10 ELSE 20 END AS base_warning",
        MYLITE_OK,
        &stmt
    );
    failures += expect_status(mylite_step(stmt), MYLITE_ROW, "CASE base warning row");
    failures += expect_string(mylite_column_text(stmt, 0), "20", "CASE base warning result");
    failures += expect_int(mylite_warning_count(database), 1, "CASE base warning count");
    mylite_finalize(stmt);
    stmt = NULL;

    failures += prepare_sql(
        database,
        "SELECT CASE WHEN 1 THEN 'yes' ELSE 'no' END AS case_text, "
        "CASE WHEN 1 THEN 10 ELSE 20 END AS case_int, "
        "CASE WHEN 0 THEN NULL END AS case_null, "
        "CASE 1 WHEN 1 THEN 2.5 ELSE 3 END AS case_decimal, "
        "CASE WHEN 1 THEN ISNULL(NULL) ELSE 0 END AS case_func",
        MYLITE_OK,
        &stmt
    );
    failures += expect_result_metadata(
        stmt,
        metadata,
        (int)(sizeof(metadata) / sizeof(metadata[0])),
        "CASE metadata"
    );
    failures += expect_status(mylite_step(stmt), MYLITE_ROW, "CASE metadata row");
    failures += expect_status(mylite_step(stmt), MYLITE_DONE, "CASE metadata done");
    mylite_finalize(stmt);
    stmt = NULL;

    failures += execute_sql(
        database,
        "CREATE TABLE case_bin_meta ("
        "id INT PRIMARY KEY, "
        "b VARBINARY(8), "
        "s VARCHAR(8))",
        MYLITE_DONE
    );
    failures += execute_sql(
        database,
        "INSERT INTO case_bin_meta VALUES (1, X'616263', 'abc')",
        MYLITE_DONE
    );
    failures += prepare_sql(
        database,
        "SELECT CASE WHEN 1 THEN b ELSE b END AS case_bin_col, "
        "CASE WHEN 1 THEN b ELSE s END AS case_mixed_bin_text, "
        "CASE WHEN 1 THEN s ELSE b END AS case_mixed_text_bin, "
        "CASE WHEN 1 THEN NULL ELSE b END AS case_null_bin "
        "FROM case_bin_meta LIMIT 0",
        MYLITE_OK,
        &stmt
    );
    failures += expect_result_metadata(
        stmt,
        binary_metadata,
        (int)(sizeof(binary_metadata) / sizeof(binary_metadata[0])),
        "CASE binary metadata"
    );
    failures += expect_status(mylite_step(stmt), MYLITE_DONE, "CASE binary metadata done");
    mylite_finalize(stmt);
    stmt = NULL;

    failures += execute_sql(
        database,
        "CREATE TABLE t ("
        "id INT PRIMARY KEY, "
        "n INT, "
        "s VARCHAR(20), "
        "marker VARCHAR(10))",
        MYLITE_DONE
    );
    failures += execute_sql(
        database,
        "INSERT INTO t VALUES "
        "(1,1,'alpha','a'),"
        "(2,-2,'Beta','b'),"
        "(3,NULL,NULL,'c'),"
        "(4,0,'gamma','d')",
        MYLITE_DONE
    );
    failures += expect_select_rows(
        database,
        "SELECT id, CASE WHEN n IS NULL THEN 'nil' ELSE CONCAT('n=', n) END AS label "
        "FROM t ORDER BY id",
        id_label_columns,
        2,
        projection_values,
        4,
        "CASE table projection"
    );
    failures += expect_select_rows(
        database,
        "SELECT id, CASE n WHEN 1 THEN 'one' WHEN -2 THEN 'minus' ELSE 'zero' END AS label "
        "FROM t ORDER BY id",
        id_label_columns,
        2,
        simple_projection_values,
        4,
        "CASE simple table projection"
    );
    failures += expect_select_rows(
        database,
        "SELECT id FROM t WHERE CASE WHEN n = 1 THEN 1 WHEN s IS NULL THEN 1 ELSE 0 END "
        "ORDER BY id",
        id_column,
        1,
        where_values,
        2,
        "CASE where"
    );
    failures += expect_select_rows(
        database,
        "SELECT id FROM t ORDER BY CASE WHEN s IS NULL THEN 0 ELSE LENGTH(s) END, id",
        id_column,
        1,
        order_values,
        4,
        "CASE order"
    );

    failures += execute_sql_expect_done_affected(
        database,
        "UPDATE t SET s = CASE WHEN n < 0 THEN LOWER(s) ELSE s END WHERE id = 2",
        1,
        "CASE update assignment"
    );
    failures += expect_select_rows(
        database,
        "SELECT id, s FROM t WHERE id = 2",
        id_s_columns,
        2,
        updated_s_values,
        1,
        "CASE update value"
    );
    failures += expect_prepare_error(
        database,
        "SELECT CASE WHEN 1 THEN 1 ELSE missing_col END FROM t "
        "LIMIT 1",
        MYLITE_EXEC_ERROR,
        "missing_col",
        "CASE binds unselected branch"
    );

    failures += execute_sql(database, "CREATE TABLE d (id INT PRIMARY KEY, v INT)", MYLITE_DONE);
    failures += execute_sql(database, "INSERT INTO d VALUES (1,10)", MYLITE_DONE);
    failures += execute_sql_expect_done_affected(
        database,
        "UPDATE d SET v = CASE WHEN 1 THEN v + 1 ELSE MOD(7,0) END WHERE id = 1",
        1,
        "CASE update unselected warning"
    );
    failures += expect_select_rows(
        database,
        "SELECT v FROM d WHERE id = 1",
        v_column,
        1,
        v_11,
        1,
        "CASE update unselected warning value"
    );
    failures += prepare_sql(
        database,
        "UPDATE d SET v = CASE WHEN 0 THEN v + 1 ELSE MOD(7,0) END WHERE id = 1",
        MYLITE_OK,
        &stmt
    );
    failures += expect_exec_error(stmt, database, "Division by 0", "CASE update selected warning");
    mylite_finalize(stmt);
    stmt = NULL;
    failures += expect_select_rows(
        database,
        "SELECT v FROM d WHERE id = 1",
        v_column,
        1,
        v_11,
        1,
        "CASE update selected warning unchanged"
    );

    failures += execute_sql_expect_done_affected(
        database,
        "DELETE FROM d WHERE CASE WHEN id = 1 THEN 0 ELSE MOD(7,0) END",
        0,
        "CASE delete unselected warning"
    );
    failures += expect_select_row_count(
        database,
        "SELECT id FROM d WHERE id = 1",
        1,
        "CASE delete unselected warning unchanged"
    );
    failures += prepare_sql(
        database,
        "DELETE FROM d WHERE CASE WHEN id = 1 THEN MOD(7,0) ELSE 0 END",
        MYLITE_OK,
        &stmt
    );
    failures += expect_exec_error(stmt, database, "Division by 0", "CASE delete selected warning");
    mylite_finalize(stmt);
    stmt = NULL;
    failures += expect_select_row_count(
        database,
        "SELECT id FROM d WHERE id = 1",
        1,
        "CASE delete selected warning unchanged"
    );

    failures += execute_sql(database, "CREATE TABLE d2 (id INT PRIMARY KEY, v INT)", MYLITE_DONE);
    failures += execute_sql(database, "INSERT INTO d2 VALUES (1,10),(2,20)", MYLITE_DONE);
    failures += prepare_sql(
        database,
        "DELETE FROM d2 WHERE CASE WHEN id = 1 THEN 0 ELSE MOD(7,0) END",
        MYLITE_OK,
        &stmt
    );
    failures += expect_exec_error(stmt, database, "Division by 0", "CASE delete later row warning");
    mylite_finalize(stmt);
    stmt = NULL;
    failures += expect_select_row_count(
        database,
        "SELECT id FROM d2",
        2,
        "CASE delete later row unchanged"
    );

    failures += execute_sql(
        database,
        "CREATE TABLE order_dml_case (id INT PRIMARY KEY, v INT, marker VARCHAR(10))",
        MYLITE_DONE
    );
    failures += execute_sql(
        database,
        "INSERT INTO order_dml_case VALUES (1,30,'a'), (2,10,'b'), (3,20,'c')",
        MYLITE_DONE
    );
    failures += execute_sql_expect_done_affected(
        database,
        "UPDATE order_dml_case "
        "SET marker = CASE WHEN id = 2 THEN 'hit' ELSE 'miss' END "
        "WHERE CASE WHEN v >= 10 THEN 1 ELSE 0 END "
        "ORDER BY CASE WHEN id = 2 THEN 0 ELSE 1 END, id "
        "LIMIT 1",
        1,
        "CASE update order"
    );
    failures += expect_select_rows(
        database,
        "SELECT id, marker FROM order_dml_case ORDER BY id",
        order_dml_columns,
        2,
        order_dml_after_update,
        3,
        "CASE update order rows"
    );
    failures += execute_sql_expect_done_affected(
        database,
        "DELETE FROM order_dml_case "
        "WHERE CASE WHEN v >= 10 THEN 1 ELSE 0 END "
        "ORDER BY CASE WHEN marker = 'hit' THEN 0 ELSE 1 END, id "
        "LIMIT 1",
        1,
        "CASE delete order"
    );
    failures += expect_select_rows(
        database,
        "SELECT id, marker FROM order_dml_case ORDER BY id",
        order_dml_columns,
        2,
        order_dml_after_delete,
        2,
        "CASE delete order rows"
    );

    mylite_close(database);
    // NOLINTEND(readability-magic-numbers)
    return failures;
}

