    static const char *const ai_info_columns[] =
        {"TABLE_NAME", "TABLE_ROWS", "AVG_ROW_LENGTH", "DATA_LENGTH", "AUTO_INCREMENT"};
    static const char *const ai_info_values[] = {"ai_shadow", "1", "16384", "16384", "11"};
