    failures += expect_int(
        (int)mylite_warning_code(database, 0),
        mysql_warning_bad_null,
        "insert ignore null id warning"
    );
    failures += expect_contains(
        mylite_warning_message(database, 0),
        "Column 'id'",
        "insert ignore null id message"
    );
