static int test_foreign_key_insert_execution(void) {
    static const char *const child_columns[] = {"id", "parent_id"};
    static const char *const child_values[] = {
        "1",
        "1",
        "2",
        NULL,
    };
    static const char *const child_after_checks_off_values[] = {
        "1",
        "1",
        "2",
        NULL,
        "3",
        "99",
    };
    static const char *const child_final_values[] = {
        "1",
        "1",
        "2",
        NULL,
        "3",
        "99",
        "5",
        "1",
        "6",
        "2",
        "7",
        "2",
        "8",
        "2",
    };
    static const char *const pair_columns[] = {"id", "a", "b"};
    static const char *const pair_values[] = {
        "1",
        NULL,
        "99",
        "2",
        "1",
        "1",
    };
    static const char *const self_columns[] = {"id", "parent_id"};
    static const char *const self_values[] = {"1", "1"};
    mylite_db *database = NULL;
    mylite_stmt *stmt = NULL;
    int failures = 0;

    failures +=
        expect_status(mylite_open_memory(&database), MYLITE_OK, "open foreign key insert database");
    failures += execute_sql(database, "CREATE DATABASE fk_insert_runtime", MYLITE_DONE);
    failures += execute_sql(database, "USE fk_insert_runtime", MYLITE_DONE);
    failures += execute_sql(database, "CREATE TABLE parent_fk (id INT PRIMARY KEY)", MYLITE_DONE);
    failures += execute_sql(
        database,
        "CREATE TABLE child_fk ("
        "id INT PRIMARY KEY, parent_id INT, "
        "FOREIGN KEY (parent_id) REFERENCES parent_fk(id))",
        MYLITE_DONE
    );
    failures += execute_sql(database, "INSERT INTO parent_fk VALUES (1),(2)", MYLITE_DONE);
    failures += execute_sql(database, "INSERT INTO child_fk VALUES (1,1),(2,NULL)", MYLITE_DONE);
    failures += expect_select_rows(
        database,
        "SELECT id, parent_id FROM child_fk ORDER BY id",
        child_columns,
        2,
        child_values,
        2,
        "foreign key insert accepts matching and null rows"
    );

    failures += prepare_sql(database, "INSERT INTO child_fk VALUES (3,99)", MYLITE_OK, &stmt);
    failures += expect_status(mylite_step(stmt), MYLITE_EXEC_ERROR, "foreign key insert rejects");
    failures += expect_contains(
        mylite_error_message(database),
        "foreign key constraint fails",
        "foreign key insert error"
    );
    mylite_finalize(stmt);
    stmt = NULL;
    failures += expect_select_rows(
        database,
        "SELECT id, parent_id FROM child_fk ORDER BY id",
        child_columns,
        2,
        child_values,
        2,
        "foreign key failed insert rolled back"
    );

    failures += execute_sql(database, "SET foreign_key_checks = 0", MYLITE_DONE);
    failures += execute_sql(database, "INSERT INTO child_fk VALUES (3,99)", MYLITE_DONE);
    failures += execute_sql(database, "SET foreign_key_checks = 1", MYLITE_DONE);
    failures += expect_select_rows(
        database,
        "SELECT id, parent_id FROM child_fk ORDER BY id",
        child_columns,
        2,
        child_after_checks_off_values,
        3,
        "foreign key checks off permits unmatched row"
    );

    failures += execute_sql_expect_done_affected(
        database,
        "INSERT IGNORE INTO child_fk VALUES (4,99)",
        0,
        "foreign key insert ignore affected rows"
    );
    failures += expect_int(mylite_warning_count(database), 1, "foreign key insert ignore warning");
    failures += expect_int(
        (int)mylite_warning_code(database, 0),
        mysql_warning_no_referenced_row,
        "foreign key insert ignore warning code"
    );
    failures += expect_select_rows(
        database,
        "SELECT id, parent_id FROM child_fk ORDER BY id",
        child_columns,
        2,
        child_after_checks_off_values,
        3,
        "foreign key insert ignore skips unmatched row"
    );

    failures +=
        execute_sql(database, "INSERT INTO child_fk SET id = 5, parent_id = 1", MYLITE_DONE);
    failures +=
        prepare_sql(database, "INSERT INTO child_fk SET id = 8, parent_id = 99", MYLITE_OK, &stmt);
    failures +=
        expect_status(mylite_step(stmt), MYLITE_EXEC_ERROR, "foreign key insert set rejects");
    mylite_finalize(stmt);
    stmt = NULL;
    failures += execute_sql(database, "REPLACE INTO child_fk VALUES (6,2)", MYLITE_DONE);
    failures += prepare_sql(database, "REPLACE INTO child_fk VALUES (9,99)", MYLITE_OK, &stmt);
    failures += expect_status(mylite_step(stmt), MYLITE_EXEC_ERROR, "foreign key replace rejects");
    mylite_finalize(stmt);
    stmt = NULL;
    failures += execute_sql(database, "INSERT INTO child_fk VALUES (7,1)", MYLITE_DONE);
    failures += execute_sql_expect_done_affected(
        database,
        "INSERT INTO child_fk VALUES (7,2) "
        "ON DUPLICATE KEY UPDATE parent_id = VALUES(parent_id)",
        2,
        "foreign key ODKU accepts matching parent"
    );
    failures += prepare_sql(
        database,
        "INSERT INTO child_fk VALUES (7,99) "
        "ON DUPLICATE KEY UPDATE parent_id = VALUES(parent_id)",
        MYLITE_OK,
        &stmt
    );
    failures += expect_status(mylite_step(stmt), MYLITE_EXEC_ERROR, "foreign key ODKU rejects");
    mylite_finalize(stmt);
    stmt = NULL;
    failures += execute_sql(database, "INSERT INTO child_fk SELECT 8, 1 FROM DUAL", MYLITE_DONE);
    failures +=
        prepare_sql(database, "INSERT INTO child_fk SELECT 9, 99 FROM DUAL", MYLITE_OK, &stmt);
    failures +=
        expect_status(mylite_step(stmt), MYLITE_EXEC_ERROR, "foreign key insert select rejects");
    mylite_finalize(stmt);
    stmt = NULL;
    failures += execute_sql_expect_done_affected(
        database,
        "INSERT IGNORE INTO child_fk SELECT 9, 99 FROM DUAL",
        0,
        "foreign key insert ignore select affected rows"
    );
    failures +=
        expect_int(mylite_warning_count(database), 1, "foreign key insert ignore select warning");
    failures += expect_int(
        (int)mylite_warning_code(database, 0),
        mysql_warning_no_referenced_row,
        "foreign key insert ignore select warning code"
    );
    failures += execute_sql_expect_done_affected(
        database,
        "INSERT INTO child_fk SELECT 8, 2 FROM DUAL "
        "ON DUPLICATE KEY UPDATE parent_id = VALUES(parent_id)",
        2,
        "foreign key insert select ODKU accepts matching parent"
    );
    failures += prepare_sql(
        database,
        "INSERT INTO child_fk SELECT 8, 99 FROM DUAL "
        "ON DUPLICATE KEY UPDATE parent_id = VALUES(parent_id)",
        MYLITE_OK,
        &stmt
    );
    failures += expect_status(
        mylite_step(stmt),
        MYLITE_EXEC_ERROR,
        "foreign key insert select ODKU rejects"
    );
    mylite_finalize(stmt);
    stmt = NULL;
    failures += expect_select_rows(
        database,
        "SELECT id, parent_id FROM child_fk ORDER BY id",
        child_columns,
        2,
        child_final_values,
        7,
        "foreign key write forms leave expected rows"
    );

    failures += execute_sql(
        database,
        "CREATE TABLE parent_pair_fk (a INT, b INT, PRIMARY KEY(a,b))",
        MYLITE_DONE
    );
    failures += execute_sql(
        database,
        "CREATE TABLE child_pair_fk ("
        "id INT PRIMARY KEY, a INT, b INT, "
        "FOREIGN KEY (a,b) REFERENCES parent_pair_fk(a,b))",
        MYLITE_DONE
    );
    failures += execute_sql(database, "INSERT INTO parent_pair_fk VALUES (1,1)", MYLITE_DONE);
    failures +=
        execute_sql(database, "INSERT INTO child_pair_fk VALUES (1,NULL,99),(2,1,1)", MYLITE_DONE);
    failures += prepare_sql(database, "INSERT INTO child_pair_fk VALUES (3,1,2)", MYLITE_OK, &stmt);
    failures +=
        expect_status(mylite_step(stmt), MYLITE_EXEC_ERROR, "composite foreign key rejects");
    mylite_finalize(stmt);
    stmt = NULL;
    failures += expect_select_rows(
        database,
        "SELECT id, a, b FROM child_pair_fk ORDER BY id",
        pair_columns,
        3,
        pair_values,
        2,
        "composite foreign key rows"
    );

    failures += execute_sql(
        database,
        "CREATE TABLE self_fk ("
        "id INT PRIMARY KEY, parent_id INT, "
        "FOREIGN KEY (parent_id) REFERENCES self_fk(id))",
        MYLITE_DONE
    );
    failures += execute_sql(database, "INSERT INTO self_fk VALUES (1,1)", MYLITE_DONE);
    failures += prepare_sql(database, "INSERT INTO self_fk VALUES (2,3)", MYLITE_OK, &stmt);
    failures += expect_status(mylite_step(stmt), MYLITE_EXEC_ERROR, "self foreign key rejects");
    mylite_finalize(stmt);
    stmt = NULL;
    failures += expect_select_rows(
        database,
        "SELECT id, parent_id FROM self_fk",
        self_columns,
        2,
        self_values,
        1,
        "self foreign key rows"
    );

    mylite_close(database);
    return failures;
}

static int test_foreign_key_parent_restrict_execution(void) {
    static const char *const parent_columns[] = {"id", "payload"};
    static const char *const parent_after_update_values[] = {
        "1",
        "11",
        "2",
        "20",
        "3",
        "30",
    };
    static const char *const parent_after_delete_values[] = {
        "1",
        "11",
        "3",
        "30",
    };
    static const char *const parent_after_checks_off_values[] = {"3", "30"};
    static const char *const child_columns[] = {"id", "parent_id"};
    static const char *const child_values[] = {
        "1",
        "1",
        "2",
        NULL,
    };
    static const char *const replace_values[] = {
        "1",
        "10",
        "2",
        "22",
    };
    static const char *const pair_columns[] = {"a", "b", "payload"};
    static const char *const pair_values[] = {"1", "1", "11", "2", "2", "20"};
    static const char *const self_columns[] = {"id", "parent_id"};
    static const char *const self_values[] = {"1", "1", "2", NULL};
    mylite_db *database = NULL;
    mylite_stmt *stmt = NULL;
    int failures = 0;

    failures += expect_status(
        mylite_open_memory(&database),
        MYLITE_OK,
        "open foreign key parent restrict database"
    );
    failures += execute_sql(database, "CREATE DATABASE fk_parent_runtime", MYLITE_DONE);
    failures += execute_sql(database, "USE fk_parent_runtime", MYLITE_DONE);
    failures += execute_sql(
        database,
        "CREATE TABLE parent_fk (id INT PRIMARY KEY, payload INT)",
        MYLITE_DONE
    );
    failures += execute_sql(
        database,
        "CREATE TABLE child_fk ("
        "id INT PRIMARY KEY, parent_id INT, "
        "FOREIGN KEY (parent_id) REFERENCES parent_fk(id))",
        MYLITE_DONE
    );
    failures +=
        execute_sql(database, "INSERT INTO parent_fk VALUES (1,10),(2,20),(3,30)", MYLITE_DONE);
    failures += execute_sql(database, "INSERT INTO child_fk VALUES (1,1),(2,NULL)", MYLITE_DONE);
    failures += execute_sql_expect_done_affected(
        database,
        "UPDATE parent_fk SET payload = 11 WHERE id = 1",
        1,
        "foreign key parent non-key update affected rows"
    );

    failures +=
        prepare_sql(database, "UPDATE parent_fk SET id = 10 WHERE id = 1", MYLITE_OK, &stmt);
    failures +=
        expect_status(mylite_step(stmt), MYLITE_EXEC_ERROR, "foreign key parent update rejects");
    failures += expect_contains(
        mylite_error_message(database),
        "Cannot delete or update a parent row",
        "foreign key parent update error"
    );
    failures += expect_int(
        (int)mylite_warning_code(database, 0),
        mysql_warning_row_is_referenced,
        "foreign key parent update error code"
    );
    mylite_finalize(stmt);
    stmt = NULL;
    failures += expect_select_rows(
        database,
        "SELECT id, payload FROM parent_fk ORDER BY id",
        parent_columns,
        2,
        parent_after_update_values,
        3,
        "foreign key parent update rolled back"
    );

    failures += prepare_sql(database, "DELETE FROM parent_fk WHERE id = 1", MYLITE_OK, &stmt);
    failures +=
        expect_status(mylite_step(stmt), MYLITE_EXEC_ERROR, "foreign key parent delete rejects");
    failures += expect_contains(
        mylite_error_message(database),
        "Cannot delete or update a parent row",
        "foreign key parent delete error"
    );
    mylite_finalize(stmt);
    stmt = NULL;
    failures += execute_sql_expect_done_affected(
        database,
        "DELETE FROM parent_fk WHERE id = 2",
        1,
        "foreign key parent delete unreferenced affected rows"
    );
    failures += expect_select_rows(
        database,
        "SELECT id, payload FROM parent_fk ORDER BY id",
        parent_columns,
        2,
        parent_after_delete_values,
        2,
        "foreign key parent delete unreferenced row"
    );
    failures += execute_sql(database, "SET foreign_key_checks = 0", MYLITE_DONE);
    failures += execute_sql_expect_done_affected(
        database,
        "DELETE FROM parent_fk WHERE id = 1",
        1,
        "foreign key checks off parent delete affected rows"
    );
    failures += execute_sql(database, "SET foreign_key_checks = 1", MYLITE_DONE);
    failures += expect_select_rows(
        database,
        "SELECT id, payload FROM parent_fk ORDER BY id",
        parent_columns,
        2,
        parent_after_checks_off_values,
        1,
        "foreign key checks off permits parent orphan"
    );
    failures += expect_select_rows(
        database,
        "SELECT id, parent_id FROM child_fk ORDER BY id",
        child_columns,
        2,
        child_values,
        2,
        "foreign key checks off leaves child rows"
    );

    failures += execute_sql(
        database,
        "CREATE TABLE replace_parent_fk (id INT PRIMARY KEY, payload INT)",
        MYLITE_DONE
    );
    failures += execute_sql(
        database,
        "CREATE TABLE replace_child_fk ("
        "id INT PRIMARY KEY, parent_id INT, "
        "FOREIGN KEY (parent_id) REFERENCES replace_parent_fk(id))",
        MYLITE_DONE
    );
    failures +=
        execute_sql(database, "INSERT INTO replace_parent_fk VALUES (1,10),(2,20)", MYLITE_DONE);
    failures += execute_sql(database, "INSERT INTO replace_child_fk VALUES (1,1)", MYLITE_DONE);
    failures +=
        prepare_sql(database, "REPLACE INTO replace_parent_fk VALUES (1,11)", MYLITE_OK, &stmt);
    failures +=
        expect_status(mylite_step(stmt), MYLITE_EXEC_ERROR, "foreign key parent replace rejects");
    mylite_finalize(stmt);
    stmt = NULL;
    failures += execute_sql_expect_done_affected(
        database,
        "REPLACE INTO replace_parent_fk VALUES (2,22)",
        2,
        "foreign key parent replace unreferenced affected rows"
    );
    failures += expect_select_rows(
        database,
        "SELECT id, payload FROM replace_parent_fk ORDER BY id",
        parent_columns,
        2,
        replace_values,
        2,
        "foreign key parent replace rows"
    );

    failures += execute_sql(
        database,
        "CREATE TABLE parent_pair_fk (a INT, b INT, payload INT, PRIMARY KEY(a,b))",
        MYLITE_DONE
    );
    failures += execute_sql(
        database,
        "CREATE TABLE child_pair_fk ("
        "id INT PRIMARY KEY, a INT, b INT, "
        "FOREIGN KEY (a,b) REFERENCES parent_pair_fk(a,b))",
        MYLITE_DONE
    );
    failures +=
        execute_sql(database, "INSERT INTO parent_pair_fk VALUES (1,1,10),(2,2,20)", MYLITE_DONE);
    failures += execute_sql(database, "INSERT INTO child_pair_fk VALUES (1,1,1)", MYLITE_DONE);
    failures += execute_sql_expect_done_affected(
        database,
        "UPDATE parent_pair_fk SET payload = 11 WHERE a = 1 AND b = 1",
        1,
        "foreign key composite parent non-key update"
    );
    failures += prepare_sql(
        database,
        "UPDATE parent_pair_fk SET a = 10 WHERE a = 1 AND b = 1",
        MYLITE_OK,
        &stmt
    );
    failures += expect_status(
        mylite_step(stmt),
        MYLITE_EXEC_ERROR,
        "foreign key composite parent update rejects"
    );
    mylite_finalize(stmt);
    stmt = NULL;
    failures +=
        prepare_sql(database, "DELETE FROM parent_pair_fk WHERE a = 1 AND b = 1", MYLITE_OK, &stmt);
    failures += expect_status(
        mylite_step(stmt),
        MYLITE_EXEC_ERROR,
        "foreign key composite parent delete rejects"
    );
    mylite_finalize(stmt);
    stmt = NULL;
    failures += expect_select_rows(
        database,
        "SELECT a, b, payload FROM parent_pair_fk ORDER BY a, b",
        pair_columns,
        3,
        pair_values,
        2,
        "foreign key composite parent rows"
    );

    failures += execute_sql(
        database,
        "CREATE TABLE self_parent_fk ("
        "id INT PRIMARY KEY, parent_id INT, "
        "FOREIGN KEY (parent_id) REFERENCES self_parent_fk(id))",
        MYLITE_DONE
    );
    failures +=
        execute_sql(database, "INSERT INTO self_parent_fk VALUES (1,1),(2,NULL)", MYLITE_DONE);
    failures += prepare_sql(database, "DELETE FROM self_parent_fk WHERE id = 1", MYLITE_OK, &stmt);
    failures += expect_status(
        mylite_step(stmt),
        MYLITE_EXEC_ERROR,
        "foreign key self parent delete rejects"
    );
    mylite_finalize(stmt);
    stmt = NULL;
    failures +=
        prepare_sql(database, "UPDATE self_parent_fk SET id = 10 WHERE id = 1", MYLITE_OK, &stmt);
    failures += expect_status(
        mylite_step(stmt),
        MYLITE_EXEC_ERROR,
        "foreign key self parent update rejects"
    );
    mylite_finalize(stmt);
    stmt = NULL;
    failures += expect_select_rows(
        database,
        "SELECT id, parent_id FROM self_parent_fk ORDER BY id",
        self_columns,
        2,
        self_values,
        2,
        "foreign key self parent rows"
    );

    failures +=
        execute_sql(database, "CREATE TABLE multi_parent_fk (id INT PRIMARY KEY)", MYLITE_DONE);
    failures += execute_sql(
        database,
        "CREATE TABLE multi_child_fk ("
        "id INT PRIMARY KEY, parent_id INT, "
        "FOREIGN KEY (parent_id) REFERENCES multi_parent_fk(id))",
        MYLITE_DONE
    );
    failures += execute_sql(database, "INSERT INTO multi_parent_fk VALUES (1)", MYLITE_DONE);
    failures += execute_sql(database, "INSERT INTO multi_child_fk VALUES (1,1)", MYLITE_DONE);
    failures += prepare_sql(
        database,
        "DELETE multi_child_fk, multi_parent_fk "
        "FROM multi_parent_fk JOIN multi_child_fk "
        "ON multi_child_fk.parent_id = multi_parent_fk.id "
        "WHERE multi_parent_fk.id = 1",
        MYLITE_OK,
        &stmt
    );
    failures +=
        expect_status(mylite_step(stmt), MYLITE_EXEC_ERROR, "foreign key multi delete rejects");
    mylite_finalize(stmt);
    stmt = NULL;

    failures +=
        execute_sql(database, "CREATE TABLE joined_parent_fk (id INT PRIMARY KEY)", MYLITE_DONE);
    failures += execute_sql(
        database,
        "CREATE TABLE joined_child_fk ("
        "id INT PRIMARY KEY, parent_id INT, "
        "FOREIGN KEY (parent_id) REFERENCES joined_parent_fk(id))",
        MYLITE_DONE
    );
    failures += execute_sql(database, "INSERT INTO joined_parent_fk VALUES (1)", MYLITE_DONE);
    failures += execute_sql(database, "INSERT INTO joined_child_fk VALUES (1,1)", MYLITE_DONE);
    failures += prepare_sql(
        database,
        "UPDATE joined_parent_fk JOIN joined_child_fk "
        "ON joined_child_fk.parent_id = joined_parent_fk.id "
        "SET joined_parent_fk.id = 10, joined_child_fk.parent_id = 10 "
        "WHERE joined_parent_fk.id = 1",
        MYLITE_OK,
        &stmt
    );
    failures +=
        expect_status(mylite_step(stmt), MYLITE_EXEC_ERROR, "foreign key joined update rejects");
    mylite_finalize(stmt);

    mylite_close(database);
    return failures;
}

static int test_foreign_key_child_update_execution(void) {
    static const char *const child_columns[] = {"id", "parent_id", "payload"};
    static const char *const child_after_null_values[] = {
        "1",
        NULL,
        "10",
        "2",
        NULL,
        "20",
    };
    static const char *const child_after_orphan_payload_values[] = {
        "1",
        "99",
        "11",
        "2",
        NULL,
        "20",
    };
    static const char *const pair_columns[] = {"id", "a", "b", "payload"};
    static const char *const pair_values[] = {
        "1",
        NULL,
        "99",
        "11",
        "2",
        "1",
        "1",
        "20",
    };
    static const char *const self_columns[] = {"id", "parent_id"};
    static const char *const self_values[] = {
        "1",
        "1",
        "2",
        "1",
    };
    static const char *const joined_columns[] = {"id", "parent_id"};
    static const char *const joined_values[] = {"1", "1"};
    mylite_db *database = NULL;
    mylite_stmt *stmt = NULL;
    int failures = 0;

    failures += expect_status(
        mylite_open_memory(&database),
        MYLITE_OK,
        "open foreign key child update database"
    );
    failures += execute_sql(database, "CREATE DATABASE fk_child_update_runtime", MYLITE_DONE);
    failures += execute_sql(database, "USE fk_child_update_runtime", MYLITE_DONE);
    failures += execute_sql(database, "CREATE TABLE parent_fk (id INT PRIMARY KEY)", MYLITE_DONE);
    failures += execute_sql(
        database,
        "CREATE TABLE child_fk ("
        "id INT PRIMARY KEY, parent_id INT, payload INT, "
        "FOREIGN KEY (parent_id) REFERENCES parent_fk(id))",
        MYLITE_DONE
    );
    failures += execute_sql(database, "INSERT INTO parent_fk VALUES (1),(2)", MYLITE_DONE);
    failures +=
        execute_sql(database, "INSERT INTO child_fk VALUES (1,1,10),(2,NULL,20)", MYLITE_DONE);
    failures += execute_sql_expect_done_affected(
        database,
        "UPDATE child_fk SET parent_id = 2 WHERE id = 1",
        1,
        "foreign key child update accepts matching parent"
    );
    failures +=
        prepare_sql(database, "UPDATE child_fk SET parent_id = 99 WHERE id = 1", MYLITE_OK, &stmt);
    failures +=
        expect_status(mylite_step(stmt), MYLITE_EXEC_ERROR, "foreign key child update rejects");
    failures += expect_contains(
        mylite_error_message(database),
        "Cannot add or update a child row",
        "foreign key child update error"
    );
    failures += expect_int(
        (int)mylite_warning_code(database, 0),
        mysql_warning_no_referenced_row,
        "foreign key child update error code"
    );
    mylite_finalize(stmt);
    stmt = NULL;
    failures += execute_sql_expect_done_affected(
        database,
        "UPDATE child_fk SET parent_id = NULL WHERE id = 1",
        1,
        "foreign key child update accepts null"
    );
    failures += expect_select_rows(
        database,
        "SELECT id, parent_id, payload FROM child_fk ORDER BY id",
        child_columns,
        3,
        child_after_null_values,
        2,
        "foreign key child update null rows"
    );
    failures += execute_sql(database, "SET foreign_key_checks = 0", MYLITE_DONE);
    failures +=
        execute_sql(database, "UPDATE child_fk SET parent_id = 99 WHERE id = 1", MYLITE_DONE);
    failures += execute_sql(database, "SET foreign_key_checks = 1", MYLITE_DONE);
    failures += execute_sql_expect_done_affected(
        database,
        "UPDATE child_fk SET payload = 11 WHERE id = 1",
        1,
        "foreign key child update ignores unchanged orphan key"
    );
    failures += expect_select_rows(
        database,
        "SELECT id, parent_id, payload FROM child_fk ORDER BY id",
        child_columns,
        3,
        child_after_orphan_payload_values,
        2,
        "foreign key child update orphan payload rows"
    );

    failures += execute_sql(
        database,
        "CREATE TABLE parent_pair_fk (a INT, b INT, PRIMARY KEY(a,b))",
        MYLITE_DONE
    );
    failures += execute_sql(
        database,
        "CREATE TABLE child_pair_fk ("
        "id INT PRIMARY KEY, a INT, b INT, payload INT, "
        "FOREIGN KEY (a,b) REFERENCES parent_pair_fk(a,b))",
        MYLITE_DONE
    );
    failures += execute_sql(database, "INSERT INTO parent_pair_fk VALUES (1,1)", MYLITE_DONE);
    failures += execute_sql(
        database,
        "INSERT INTO child_pair_fk VALUES (1,NULL,99,20),(2,1,1,20)",
        MYLITE_DONE
    );
    failures += execute_sql_expect_done_affected(
        database,
        "UPDATE child_pair_fk SET payload = 11 WHERE id = 1",
        1,
        "foreign key composite child unchanged null part"
    );
    failures +=
        prepare_sql(database, "UPDATE child_pair_fk SET b = 2 WHERE id = 2", MYLITE_OK, &stmt);
    failures += expect_status(
        mylite_step(stmt),
        MYLITE_EXEC_ERROR,
        "foreign key composite child update rejects"
    );
    mylite_finalize(stmt);
    stmt = NULL;
    failures += expect_select_rows(
        database,
        "SELECT id, a, b, payload FROM child_pair_fk ORDER BY id",
        pair_columns,
        4,
        pair_values,
        2,
        "foreign key composite child rows"
    );

    failures += execute_sql(
        database,
        "CREATE TABLE self_child_fk ("
        "id INT PRIMARY KEY, parent_id INT, "
        "FOREIGN KEY (parent_id) REFERENCES self_child_fk(id))",
        MYLITE_DONE
    );
    failures +=
        execute_sql(database, "INSERT INTO self_child_fk VALUES (1,NULL),(2,1)", MYLITE_DONE);
    failures += execute_sql_expect_done_affected(
        database,
        "UPDATE self_child_fk SET parent_id = 1 WHERE id = 1",
        1,
        "foreign key self child update accepts same row"
    );
    failures += prepare_sql(
        database,
        "UPDATE self_child_fk SET parent_id = 99 WHERE id = 2",
        MYLITE_OK,
        &stmt
    );
    failures += expect_status(
        mylite_step(stmt),
        MYLITE_EXEC_ERROR,
        "foreign key self child update rejects"
    );
    mylite_finalize(stmt);
    stmt = NULL;
    failures += expect_select_rows(
        database,
        "SELECT id, parent_id FROM self_child_fk ORDER BY id",
        self_columns,
        2,
        self_values,
        2,
        "foreign key self child rows"
    );

    failures +=
        execute_sql(database, "CREATE TABLE joined_parent_fk (id INT PRIMARY KEY)", MYLITE_DONE);
    failures += execute_sql(
        database,
        "CREATE TABLE joined_child_fk ("
        "id INT PRIMARY KEY, parent_id INT, "
        "FOREIGN KEY (parent_id) REFERENCES joined_parent_fk(id))",
        MYLITE_DONE
    );
    failures += execute_sql(database, "INSERT INTO joined_parent_fk VALUES (1)", MYLITE_DONE);
    failures += execute_sql(database, "INSERT INTO joined_child_fk VALUES (1,1)", MYLITE_DONE);
    failures += prepare_sql(
        database,
        "UPDATE joined_child_fk JOIN joined_parent_fk "
        "ON joined_child_fk.parent_id = joined_parent_fk.id "
        "SET joined_child_fk.parent_id = 99 "
        "WHERE joined_child_fk.id = 1",
        MYLITE_OK,
        &stmt
    );
    failures += expect_status(
        mylite_step(stmt),
        MYLITE_EXEC_ERROR,
        "foreign key joined child update rejects"
    );
    mylite_finalize(stmt);
    stmt = NULL;
    failures += expect_select_rows(
        database,
        "SELECT id, parent_id FROM joined_child_fk",
        joined_columns,
        2,
        joined_values,
        1,
        "foreign key joined child rows"
    );

    mylite_close(database);
    return failures;
}

