static int expect_information_schema_tables_views(mylite_db *database) {
    static const char *const expected_tables[] = {
        "CHARACTER_SETS",
        "COLLATION_CHARACTER_SET_APPLICABILITY",
        "CHECK_CONSTRAINTS",
        "COLLATIONS",
        "COLUMNS",
        "ENGINES",
        "SCHEMATA",
        "KEYWORDS",
        "KEY_COLUMN_USAGE",
        "REFERENTIAL_CONSTRAINTS",
        "STATISTICS",
        "TABLES",
        "TABLE_CONSTRAINTS",
    };
    mylite_stmt *stmt = NULL;
    int failures =
        prepare_sql(database, "SELECT * FROM INFORMATION_SCHEMA.TABLES", MYLITE_OK, &stmt);
    int seen[information_schema_view_count] = {0};

    while (failures == 0) {
        int status = mylite_step(stmt);
        const char *schema_name = NULL;
        const char *table_name = NULL;

        if (status == MYLITE_DONE) {
            break;
        }
        failures += expect_status(status, MYLITE_ROW, "tables row");
        if (failures != 0) {
            break;
        }

        schema_name = mylite_column_text(stmt, tables_schema_column);
        table_name = mylite_column_text(stmt, tables_name_column);
        if (schema_name == NULL || strcmp(schema_name, "information_schema") != 0) {
            continue;
        }

        for (int index = 0; index < information_schema_view_count; ++index) {
            if (strcmp(table_name, expected_tables[index]) == 0) {
                seen[index] = 1;
                failures += expect_string(
                    mylite_column_text(stmt, tables_catalog_column),
                    "def",
                    "tables catalog"
                );
                failures += expect_string(
                    mylite_column_text(stmt, tables_type_column),
                    "SYSTEM VIEW",
                    "tables type"
                );
                failures += expect_null_text(
                    mylite_column_text(stmt, tables_engine_column),
                    "tables engine"
                );
                failures += expect_int64(
                    mylite_column_int64(stmt, tables_version_column),
                    information_schema_table_version,
                    "tables version"
                );
                failures +=
                    expect_int64(mylite_column_int64(stmt, tables_rows_column), 0, "tables rows");
                failures += expect_string(
                    mylite_column_text(stmt, tables_avg_row_length_column),
                    "0",
                    "tables average row length"
                );
                failures += expect_string(
                    mylite_column_text(stmt, tables_data_length_column),
                    "0",
                    "tables data length"
                );
                failures += expect_string(
                    mylite_column_text(stmt, tables_max_data_length_column),
                    "0",
                    "tables max data length"
                );
                failures += expect_string(
                    mylite_column_text(stmt, tables_index_length_column),
                    "0",
                    "tables index length"
                );
                failures += expect_string(
                    mylite_column_text(stmt, tables_data_free_column),
                    "0",
                    "tables data free"
                );
                failures += expect_null_text(
                    mylite_column_text(stmt, tables_auto_increment_column),
                    "tables auto increment"
                );
                failures += expect_datetime_text(
                    mylite_column_text(stmt, tables_create_time_column),
                    0U,
                    "tables create time"
                );
                failures += expect_null_text(
                    mylite_column_text(stmt, tables_update_time_column),
                    "tables update time"
                );
                failures += expect_null_text(
                    mylite_column_text(stmt, tables_check_time_column),
                    "tables check time"
                );
                failures += expect_null_text(
                    mylite_column_text(stmt, tables_collation_column),
                    "tables table collation"
                );
                failures += expect_string(
                    mylite_column_text(stmt, tables_comment_column),
                    "",
                    "tables comment"
                );
            }
        }
    }

    for (int index = 0; index < information_schema_view_count; ++index) {
        if (!seen[index]) {
            fprintf(
                stderr,
                "tables did not return information_schema.%s\n",
                expected_tables[index]
            );
            failures = 1;
        }
    }

    mylite_finalize(stmt);
    return failures;
}

static int expect_information_schema_keywords_first_rows(mylite_db *database, const char *sql) {
    static const char *const expected_words[] = {
        "ACCESSIBLE",
        "ACCOUNT",
        "ACTION",
        "ACTIVE",
        "ADD",
    };

    enum { expected_keyword_prefix_count = sizeof(expected_words) / sizeof(expected_words[0]) };

    static const int64_t expected_reserved[] = {1, 0, 0, 0, 1};
    static const char *const columns[] = {"WORD", "RESERVED"};
    mylite_stmt *stmt = NULL;
    int failures = prepare_sql(database, sql, MYLITE_OK, &stmt);

    failures += expect_column_names(stmt, columns, 2, sql);
    for (int index = 0; index < expected_keyword_prefix_count; ++index) {
        failures += expect_status(mylite_step(stmt), MYLITE_ROW, sql);
        failures += expect_string(mylite_column_text(stmt, 0), expected_words[index], sql);
        failures += expect_int64(mylite_column_int64(stmt, 1), expected_reserved[index], sql);
    }
    failures += expect_int64(mylite_affected_rows(stmt), -1, sql);

    mylite_finalize(stmt);
    return failures;
}

static int expect_information_schema_keywords_matches_catalog(mylite_db *database) {
    static const char *const columns[] = {"WORD", "RESERVED"};
    mylite_stmt *stmt = NULL;
    size_t index = 0U;
    int failures =
        prepare_sql(database, "SELECT * FROM INFORMATION_SCHEMA.KEYWORDS", MYLITE_OK, &stmt);

    failures += expect_column_names(stmt, columns, 2, "information schema keywords catalog");
    for (; index < mylite_sql_keyword_catalog_count(); ++index) {
        const char *expected_word = NULL;
        const char *actual_word = NULL;
        unsigned int expected_flags = 0U;
        int64_t expected_reserved = 0;

        failures += expect_status(mylite_step(stmt), MYLITE_ROW, "information schema keyword row");
        if (!mylite_sql_keyword_catalog_at(index, &expected_word, &expected_flags)) {
            fprintf(stderr, "keyword catalog did not return index %zu\n", index);
            failures = 1;
            break;
        }
        actual_word = mylite_column_text(stmt, 0);
        expected_reserved = (expected_flags & MYLITE_SQL_KEYWORD_RESERVED) != 0U ? 1 : 0;
        failures += expect_string(actual_word, expected_word, "information schema keyword word");
        failures += expect_int64(
            mylite_column_int64(stmt, 1),
            expected_reserved,
            "information schema keyword reserved"
        );
        if (failures != 0) {
            break;
        }
    }
    failures += expect_status(mylite_step(stmt), MYLITE_DONE, "information schema keyword end");

    mylite_finalize(stmt);
    return failures;
}

static int expect_information_schema_keyword_row(
    mylite_db *database,
    const char *word,
    int64_t expected_reserved
) {
    mylite_stmt *stmt = NULL;
    int saw_word = 0;
    int failures =
        prepare_sql(database, "SELECT * FROM INFORMATION_SCHEMA.KEYWORDS", MYLITE_OK, &stmt);

    while (failures == 0) {
        int status = mylite_step(stmt);
        const char *actual_word = NULL;

        if (status == MYLITE_DONE) {
            break;
        }
        failures += expect_status(status, MYLITE_ROW, word);
        if (failures != 0) {
            break;
        }

        actual_word = mylite_column_text(stmt, 0);
        if (actual_word != NULL && strcmp(actual_word, word) == 0) {
            saw_word = 1;
            failures += expect_int64(mylite_column_int64(stmt, 1), expected_reserved, word);
            break;
        }
    }

    if (!saw_word) {
        fprintf(stderr, "keywords did not return required word '%s'\n", word);
        failures = 1;
    }

    mylite_finalize(stmt);
    return failures;
}

