static int expect_information_schema_statistics_row(
    mylite_db *database,
    const struct expected_statistics_row *expected
) {
    mylite_stmt *stmt = NULL;
    int failures =
        prepare_sql(database, "SELECT * FROM INFORMATION_SCHEMA.STATISTICS", MYLITE_OK, &stmt);
    int saw_row = 0;

    while (failures == 0) {
        int status = mylite_step(stmt);
        const char *table_name = NULL;
        const char *index_name = NULL;
        int64_t seq_in_index = 0;

        if (status == MYLITE_DONE) {
            break;
        }
        failures += expect_status(status, MYLITE_ROW, "statistics row");
        if (failures != 0) {
            break;
        }

        table_name = mylite_column_text(stmt, statistics_table_name_column);
        index_name = mylite_column_text(stmt, statistics_index_name_column);
        seq_in_index = mylite_column_int64(stmt, statistics_seq_column);
        if (strcmp(table_name, expected->table_name) != 0 ||
            strcmp(index_name, expected->index_name) != 0 ||
            seq_in_index != expected->seq_in_index) {
            continue;
        }

        saw_row = 1;
        failures += expect_int64(
            mylite_column_int64(stmt, statistics_non_unique_column),
            expected->non_unique,
            "statistics non unique"
        );
        failures += expect_string(
            mylite_column_text(stmt, statistics_column_name_column),
            expected->column_name,
            "statistics column name"
        );
        if (expected->collation == NULL) {
            failures += expect_null_text(
                mylite_column_text(stmt, statistics_collation_column),
                "statistics collation"
            );
        } else {
            failures += expect_string(
                mylite_column_text(stmt, statistics_collation_column),
                expected->collation,
                "statistics collation"
            );
        }
        failures += expect_string(
            mylite_column_text(stmt, statistics_cardinality_column),
            "0",
            "statistics cardinality"
        );
        if (expected->sub_part == NULL) {
            failures += expect_null_text(
                mylite_column_text(stmt, statistics_sub_part_column),
                "statistics sub part"
            );
        } else {
            failures += expect_string(
                mylite_column_text(stmt, statistics_sub_part_column),
                expected->sub_part,
                "statistics sub part"
            );
        }
        failures += expect_string(
            mylite_column_text(stmt, statistics_index_type_column),
            expected->index_type == NULL ? "BTREE" : expected->index_type,
            "statistics index type"
        );
        failures += expect_string(
            mylite_column_text(stmt, statistics_index_comment_column),
            expected->index_comment,
            "statistics index comment"
        );
        failures += expect_string(
            mylite_column_text(stmt, statistics_visible_column),
            expected->visible,
            "statistics visibility"
        );
        break;
    }

    if (!saw_row) {
        fprintf(
            stderr,
            "statistics did not return row for %s.%s seq %" PRId64 "\n",
            expected->table_name,
            expected->index_name,
            expected->seq_in_index
        );
        failures = 1;
    }

    mylite_finalize(stmt);
    return failures;
}

